import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`cover-letter`,heroTitle:`Generate tailored cover letters in minutes`,heroSubtitle:`Perplexity Computer analyzes your resume, matches your experience to each role, and writes personalized cover letters automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your resume`,inputFileAccept:`.pdf,.doc,.docx`,inputFilePrefill:`Review the uploaded resume and extract the candidate's skills, experience, job titles, accomplishments, and education. Then ask me which jobs I'm applying to. I'll provide job titles, company names, and job description URLs or text. For each role: 1) Analyze the job description's requirements, preferred qualifications, and key language. 2) Identify the candidate's most relevant experience, skills, and accomplishments that map to each requirement. 3) Mirror the job description's specific terminology and tone throughout the cover letter. 4) Write a tailored cover letter that opens with a compelling hook, highlights two or three of the strongest experience matches with concrete results, and closes with a confident call to action. 5) Keep each letter under one page, professional, and specific. Deliver all cover letters in a single document with the job title and company name as headers for each one.`,heroOverlaySteps:[`Extracting your skills, experience, and accomplishments from your resume`,`Analyzing each job description for requirements and key language`,`Matching your strongest experience to each role's priorities`,`Tailored cover letters with role-specific language ready to send`],generatingSteps:[`Parsing the uploaded file to extract your experience, skills, and accomplishments`,`Designing an agent to analyze job descriptions and mirror each role's language`,`Configuring experience-to-requirement matching and cover letter generation for each role`,`Setting up delivery of tailored cover letters organized by job and company`],featureSectionTitle:`From resume to tailored cover letters`,featureCardTitles:[`Connects to your career tools`,`Outputs you can send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Notion, and Dropbox Sign plug into one workflow so cover letters move directly from generation to application.`,`Role-specific cover letters. Keyword-matched language. Quantified accomplishment highlights. One document with every letter ready to copy into your applications.`],capabilitySectionTitle:`Your career coach, on autopilot`,capabilitySectionSubtitle:`Upload your resume, list your target roles, and get back polished cover letters.`,capabilityCards:[{title:`Resume Analysis`,description:`Computer can parse your resume to extract skills, accomplishments, metrics, and career themes and build a complete profile of your strengths.`},{title:`Job Description Matching`,description:`Computer can analyze each job description and map your most relevant experience to every requirement so nothing important gets missed.`},{title:`Language Mirroring`,description:`Computer can extract the terminology, tone, and keywords from each job posting and weave them naturally into your cover letter.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Google Drive, Notion, and more to keep your applications organized across every role.`},{title:`Remember & Improve`,description:`Computer can remember your resume, past cover letters, and preferred tone across sessions so each new letter builds on what works.`},{title:`New Role Alerts`,description:`Computer can monitor job boards for new postings matching your profile and alert you when a high-fit role appears.`}]});export{t as default};
